2e\u0641\u0636 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0735","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0735-Bn6TXyO.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0735-Bn6TXyO.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"783ac8f1-5833-5939-84a2-2b91c4785758","source_id":"3679","name_en":"sit-up with arms on chest","name_ar":"\u0627\u0644\u062c\u0644\u0648\u0633 \u0645\u0639 \u0648\u0636\u0639 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0635\u062f\u0631","match_names":["sit-up with arms on chest"],"muscle":"core","equipment":"bodyweight","aliases":["sit-up with arms on chest"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie flat on your back with your knees bent and feet flat on the ground.\nCross your arms over your chest.\nEngaging your abs, lift your upper body off the ground towards your knees.\nPause for a moment at the top, then slowly lower your upper body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0627\u0639\u0628\u0631 \u0630\u0631\u0627\u0639\u064a\u0643 \u0639\u0644\u0649 \u0635\u062f\u0631\u0643.\n\u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643\u060c \u0627\u0631\u0641\u0639 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u0628\u0627\u062a\u062c\u0627\u0647 \u0631\u0643\u0628\u062a\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3679","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3679-6ZCiYWQ.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3679-6ZCiYWQ.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"10a7dfc9-ec33-5422-85de-5718a4086143","source_id":"3361","name_en":"skater hops","name_ar":"\u0627\u0644\u0642\u0641\u0632\u0627\u062a \u0627\u0644\u0645\u062a\u0632\u0644\u062c","match_names":["skater hops"],"muscle":"cardio","equipment":"bodyweight","aliases":["skater hops"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart.\nBend your knees slightly and jump to the right, landing on your right foot.\nAs you land, swing your left leg behind your right leg and tap the ground with your left toes.\nImmediately jump to the left, landing on your left foot.\nAs you land, swing your right leg behind your left leg and tap the ground with your right toes.\nContinue alternating sides, jumping and tapping the ground with each leg.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b \u0648\u0627\u0642\u0641\u0632 \u0625\u0644\u0649 \u0627\u0644\u064a\u0645\u064a\u0646\u060c \u0648\u0647\u0628\u0637 \u0639\u0644\u0649 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649.\n\u0623\u062b\u0646\u0627\u0621 \u0647\u0628\u0648\u0637\u0643\u060c \u0642\u0645 \u0628\u0623\u0631\u062c\u062d\u0629 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u062e\u0644\u0641 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0628\u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649.\n\u0627\u0642\u0641\u0632 \u0639\u0644\u0649 \u0627\u0644\u0641\u0648\u0631 \u0625\u0644\u0649 \u0627\u0644\u064a\u0633\u0627\u0631\u060c \u0648\u0647\u0628\u0637 \u0639\u0644\u0649 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649.\n\u0623\u062b\u0646\u0627\u0621 \u0647\u0628\u0648\u0637\u0643\u060c \u0642\u0645 \u0628\u0623\u0631\u062c\u062d\u0629 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u062e\u0644\u0641 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0628\u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646\u060c \u0648\u0627\u0644\u0642\u0641\u0632 \u0648\u0627\u0644\u0646\u0642\u0631 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0628\u0643\u0644 \u0633\u0627\u0642.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3361","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"cardio","classification_status":"needs_review","source_target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3361-zfNHMN9.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3361-zfNHMN9.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"5d686d21-9eec-5fee-8c34-223c17a3d113","source_id":"2142","name_en":"ski ergometer","name_ar":"\u0645\u0642\u064a\u0627\u0633 \u0639\u0645\u0644 \u0627\u0644\u062a\u0632\u0644\u062c","match_names":["ski ergometer"],"muscle":"triceps","equipment":"skierg_machine","aliases":["ski ergometer"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the seat height and footrests to a comfortable position.\nGrasp the handles with an overhand grip, palms facing down.\nSit up straight with your feet flat on the footrests.\nExtend your arms straight out in front of you, keeping your elbows slightly bent.\nEngage your triceps and push the handles down towards your thighs.\nPause for a moment at the bottom, then slowly return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0645\u0633\u0627\u0646\u062f \u0627\u0644\u0642\u062f\u0645\u064a\u0646 \u0639\u0644\u0649 \u0648\u0636\u0639 \u0645\u0631\u064a\u062d.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0642\u0628\u0636\u0629 \u064a\u062f\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0633\u0641\u0644.\n\u0627\u062c\u0644\u0633 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0645\u0633\u0627\u0646\u062f \u0627\u0644\u0642\u062f\u0645\u064a\u0646.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0623\u0645\u0627\u0645\u0643\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0627\u0644\u0639\u0636\u0644\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633 \u0648\u0627\u062f\u0641\u0639 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0644\u0644\u0623\u0633\u0641\u0644 \u0646\u062d\u0648 \u0641\u062e\u0630\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2142","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["shoulders","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2142-vpQaQkH.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2142-vpQaQkH.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"bdc57d4e-c983-506d-89f9-a7ea3adafa48","source_id":"3671","name_en":"ski step","name_ar":"\u062e\u0637\u0648\u0629 \u0627\u0644\u062a\u0632\u0644\u062c","match_names":["ski step"],"muscle":"cardio","equipment":"bodyweight","aliases":["ski step"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart.\nBend your knees slightly and keep your back straight.\nJump to the right, landing on your right foot while swinging your left leg behind your right leg.\nImmediately jump to the left, landing on your left foot while swinging your right leg behind your left leg.\nContinue alternating jumps from side to side, mimicking a skiing motion.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643.\n\u0627\u0642\u0641\u0632 \u0625\u0644\u0649 \u0627\u0644\u064a\u0645\u064a\u0646\u060c \u0648\u0627\u0647\u0628\u0637 \u0639\u0644\u0649 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0628\u064a\u0646\u0645\u0627 \u062a\u0624\u0631\u062c\u062d \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u062e\u0644\u0641 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0645\u0646\u0649.\n\u0627\u0642\u0641\u0632 \u0639\u0644\u0649 \u0627\u0644\u0641\u0648\u0631 \u0625\u0644\u0649 \u0627\u0644\u064a\u0633\u0627\u0631\u060c \u0648\u0647\u0628\u0637 \u0639\u0644\u0649 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0628\u064a\u0646\u0645\u0627 \u062a\u0624\u0631\u062c\u062d \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u062e\u0644\u0641 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0633\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0642\u0641\u0632 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0645\u0646 \u062c\u0627\u0646\u0628 \u0625\u0644\u0649 \u0622\u062e\u0631\u060c \u0645\u0642\u0644\u062f\u064b\u0627 \u062d\u0631\u0643\u0629 \u0627\u0644\u062a\u0632\u0644\u062c.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3671","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"cardio","classification_status":"needs_review","source_target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3671-5MRH8H2.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3671-5MRH8H2.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"bf09fe32-8d0f-51a7-84ee-539e64ee5d2e","source_id":"3304","name_en":"skin the cat","name_ar":"\u062c\u0644\u062f \u0627\u0644\u0642\u0637\u0629","match_names":["skin the cat"],"muscle":"back","equipment":"bodyweight","aliases":["skin the cat"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start by hanging from a bar with your arms fully extended and your body relaxed.\nEngage your core and lift your legs up, bringing your knees towards your chest.\nContinue to lift your legs up and over your head, allowing your body to pass through the arms.\nOnce your legs are fully extended over your head, begin to lower them back down towards the starting position.\nAs you lower your legs, allow your body to pass back through the arms until you are hanging with your arms fully extended again.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0645\u0646 \u0627\u0644\u0628\u0627\u0631 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u0627\u0633\u062a\u0631\u062e\u0627\u0621 \u062c\u0633\u0645\u0643.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0631\u0641\u0639 \u0633\u0627\u0642\u064a\u0643 \u0644\u0644\u0623\u0639\u0644\u0649\u060c \u0648\u062c\u0644\u0628 \u0631\u0643\u0628\u062a\u064a\u0643 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0631\u0641\u0639 \u0633\u0627\u0642\u064a\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0648\u0641\u0648\u0642 \u0631\u0623\u0633\u0643\u060c \u0645\u0645\u0627 \u064a\u0633\u0645\u062d \u0644\u062c\u0633\u0645\u0643 \u0628\u0627\u0644\u0645\u0631\u0648\u0631 \u0639\u0628\u0631 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646.\n\u0628\u0645\u062c\u0631\u062f \u0623\u0646 \u062a\u0645\u062f \u0633\u0627\u0642\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0641\u0648\u0642 \u0631\u0623\u0633\u0643\u060c \u0627\u0628\u062f\u0623 \u0641\u064a \u062e\u0641\u0636\u0647\u0645\u0627 \u0644\u0644\u0623\u0633\u0641\u0644 \u0628\u0627\u062a\u062c\u0627\u0647 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0623\u062b\u0646\u0627\u0621 \u0642\u064a\u0627\u0645\u0643 \u0628\u062e\u0641\u0636 \u0633\u0627\u0642\u064a\u0643\u060c \u0627\u0633\u0645\u062d \u0644\u062c\u0633\u0645\u0643 \u0628\u0627\u0644\u0645\u0631\u0648\u0631 \u0644\u0644\u062e\u0644\u0641 \u0639\u0628\u0631 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646 \u062d\u062a\u0649 \u062a\u0635\u0628\u062d \u0645\u0639\u0644\u0642\u064b\u0627 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0645\u062a\u062f\u062a\u064a\u0646 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3304","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["shoulders","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3304-MSfvriJ.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3304-MSfvriJ.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"cd0044ff-9ce0-51f0-89e5-964d954f25b2","source_id":"1425","name_en":"sled 45 degrees one leg press","name_ar":"\u0632\u0644\u0627\u062c\u0629 \u0628\u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629\u060c \u0627\u0636\u063a\u0637 \u0628\u0633\u0627\u0642 \u0648\u0627\u062d\u062f\u0629","match_names":["sled 45 degrees one leg press"],"muscle":"glutes","equipment":"sled_machine","aliases":["sled 45 degrees one leg press"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the sled machine to a 45-degree angle.\nSit on the sled machine with your back against the pad and your feet on the footplate.\nPlace one foot on the footplate and extend your leg, pushing the sled away from you.\nSlowly bend your knee and lower the sled back to the starting position.\nRepeat with the other leg.\nContinue alternating legs for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0622\u0644\u0629 \u0627\u0644\u0645\u0632\u0644\u062c\u0629 \u0639\u0644\u0649 \u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0622\u0644\u0629 \u0627\u0644\u0632\u0644\u0627\u062c\u0629 \u0645\u0639 \u0648\u0636\u0639 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0648\u0633\u0627\u062f\u0629 \u0648\u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0648\u0633\u0627\u062f\u0629 \u0627\u0644\u0642\u062f\u0645.\n\u0636\u0639 \u0642\u062f\u0645\u064b\u0627 \u0648\u0627\u062d\u062f\u0629 \u0639\u0644\u0649 \u0627\u0644\u0635\u0641\u064a\u062d\u0629 \u0627\u0644\u0642\u062f\u0645\u064a\u0629 \u0648\u0645\u062f\u062f \u0633\u0627\u0642\u0643\u060c \u0648\u0627\u062f\u0641\u0639 \u0627\u0644\u0645\u0632\u0644\u062c\u0629 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646\u0643.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u0643 \u0628\u0628\u0637\u0621 \u062b\u0645 \u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u0632\u0644\u0627\u062c\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0645\u0639 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0623\u062e\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1425","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":