4\u064a\u0643 \u0648\u0633\u0627\u0642\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0642\u0645 \u0628\u062e\u0641\u0636 \u0645\u0646\u0635\u0629 \u0627\u0644\u0632\u0644\u0627\u062c\u0629 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0738","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"calves","secondary_muscles":["hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0738-qCNVnaU.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0738-qCNVnaU.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"7c372b0c-f82b-5554-83c5-5f1eac8aec26","source_id":"0739","name_en":"sled 45\u0432\u00b0 leg press","name_ar":"\u0645\u0632\u0644\u062c\u0629 \u0636\u063a\u0637 \u0627\u0644\u0633\u0627\u0642 \u0628\u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629","match_names":["sled 45\u0432\u00b0 leg press"],"muscle":"glutes","equipment":"sled_machine","aliases":["sled 45\u0432\u00b0 leg press"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the seat and footplate of the sled machine to a comfortable position.\nSit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.\nGrip the handles on the sides of the seat for stability.\nPush the footplate away from your body by extending your legs, keeping your heels on the footplate.\nContinue pushing until your legs are almost fully extended, but without locking your knees.\nPause for a moment at the top of the movement, then slowly lower the footplate back towards your body by bending your knees.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0644\u0648\u062d\u0629 \u0627\u0644\u0642\u062f\u0645 \u0644\u0622\u0644\u0629 \u0627\u0644\u0632\u0644\u0627\u062c\u0629 \u0639\u0644\u0649 \u0648\u0636\u0639 \u0645\u0631\u064a\u062d.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0622\u0644\u0629 \u0627\u0644\u0632\u0644\u0627\u062c\u0629 \u0645\u0639 \u0648\u0636\u0639 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0645\u0633\u0646\u062f \u0627\u0644\u0638\u0647\u0631\u060c \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u062a\u0628\u0627\u0639\u062f\u062a\u064a\u0646 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0639\u0644\u0649 \u0644\u0648\u062d\u0629 \u0627\u0644\u0642\u062f\u0645.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0627\u0644\u0645\u0648\u062c\u0648\u062f\u0629 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a \u0627\u0644\u0645\u0642\u0639\u062f \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u062b\u0628\u0627\u062a.\n\u0627\u062f\u0641\u0639 \u0635\u0641\u064a\u062d\u0629 \u0627\u0644\u0642\u062f\u0645 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0645\u062f \u0633\u0627\u0642\u064a\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0643\u0639\u0628\u064a\u0643 \u0639\u0644\u0649 \u0635\u0641\u064a\u062d\u0629 \u0627\u0644\u0642\u062f\u0645.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062f\u0641\u0639 \u062d\u062a\u0649 \u062a\u0635\u0628\u062d \u0633\u0627\u0642\u064a\u0643 \u0645\u0645\u062a\u062f\u062a\u064a\u0646 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u062a\u0642\u0631\u064a\u0628\u064b\u0627\u060c \u0648\u0644\u0643\u0646 \u062f\u0648\u0646 \u0642\u0641\u0644 \u0631\u0643\u0628\u062a\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u0635\u0641\u064a\u062d\u0629 \u0627\u0644\u0642\u062f\u0645\u064a\u0629 \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0739","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0739-10Z2DXU.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0739-10Z2DXU.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribut