623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0627\u0644\u0645\u0648\u062c\u0648\u062f\u0629 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a \u0627\u0644\u0645\u0642\u0639\u062f \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u062b\u0628\u0627\u062a.\n\u0627\u062f\u0641\u0639 \u0635\u0641\u064a\u062d\u0629 \u0627\u0644\u0642\u062f\u0645 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0645\u062f \u0633\u0627\u0642\u064a\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0643\u0639\u0628\u064a\u0643 \u0639\u0644\u0649 \u0635\u0641\u064a\u062d\u0629 \u0627\u0644\u0642\u062f\u0645.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0645\u0645\u062a\u062f \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0628\u0637\u0621 \u0648\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u0635\u0641\u064a\u062d\u0629 \u0627\u0644\u0642\u062f\u0645\u064a\u0629 \u0646\u062d\u0648 \u062c\u0633\u0645\u0643\u060c \u0645\u0639 \u0627\u0644\u062a\u062d\u0643\u0645 \u0641\u064a \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1464","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1464-yn2lLSI.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1464-yn2lLSI.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"6153c48b-c4f6-5a04-81d7-2e143e374bd8","source_id":"1463","name_en":"sled 45\u00b0 leg press (side pov)","name_ar":"\u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0633\u0627\u0642 \u0628\u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629 (\u0627\u0644\u0631\u0624\u064a\u0629 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0629)","match_names":["sled 45\u00b0 leg press (side pov)"],"muscle":"glutes","equipment":"sled_machine","aliases":["sled 45\u00b0 leg press (side pov)"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the seat of the sled machine so that your knees are at a 90-degree angle when your feet are on the footplate.\nSit on the sled machine with your back flat against the backrest and your feet shoulder-width apart on the footplate.\nGrip the handles on the sides of the seat for stability.\nPush against the footplate to extend your legs, straightening them completely.\nPause for a moment at the top, then slowly bend your knees to lower the footplate back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0645\u0642\u0639\u062f \u0622\u0644\u0629 \u0627\u0644\u0632\u0644\u0627\u062c\u0629 \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629 \u0639\u0646\u062f\u0645\u0627 \u062a\u0643\u0648\u0646 \u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0635\u0641\u064a\u062d\u0629 \u0627\u0644\u0642\u062f\u0645.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0622\u0644\u0629 \u0627\u0644\u0632\u0644\u0627\u062c\u0627\u062a \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u0637\u062d\u064b\u0627 \u0639\u0644\u0649 \u0645\u0633\u0646\u062f \u0627\u0644\u0638\u0647\u0631 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u062a\u0628\u0627\u0639\u062f\u062a\u064a\u0646 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0639\u0644\u0649 \u0635\u0641\u064a\u062d\u0629 \u0627\u0644\u0642\u062f\u0645.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0627\u0644\u0645\u0648\u062c\u0648\u062f\u0629 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a \u0627\u0644\u0645\u0642\u0639\u062f \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u062b\u0628\u0627\u062a.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0635\u0641\u064a\u062d\u0629 \u0627\u0644\u0642\u062f\u0645\u064a\u0629 \u0644\u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u064a\u0643\u060c \u0648\u062a\u0642\u0648\u064a\u0645\u0647\u0645\u0627 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0628\u0637\u0621 \u0644\u062e\u0641\u0636 \u0627\u0644\u0635\u0641\u064a\u062d\u0629 \u0627\u0644\u0642\u062f\u0645\u064a\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1463","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1463-2Qh2J1e.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1463-2Qh2J1e.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"e426e175-914f-53ec-88af-2be0cef0924d","source_id":"0740","name_en":"sled 45\u0432\u00b0 leg wide press","name_ar":"\u0632\u0644\u0627\u062c\u0629 45 \u062f\u0631\u062c\u0629 \u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0646\u0637\u0627\u0642 \u0648\u0627\u0633\u0639 \u0644\u0644\u0633\u0627\u0642","match_names":["sled 45\u0432\u00b0 leg wide press"],"muscle":"glutes","equipment":"sled_machine","aliases":["sled 45\u0432\u00b0 leg wide press"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the sled machine to a 45-degree angle.\nSit on the sled machine with your back against the pad and your feet on the foot platform.\nPosition your feet wider than shoulder-width apart.\nPush against the foot platform to extend your legs and straighten your knees.\nPause for a moment at the end of the movement, then slowly bend your knees to return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0622\u0644\u0629 \u0627\u0644\u0645\u0632\u0644\u062c\u0629 \u0639\u0644\u0649 \u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0622\u0644\u0629 \u0627\u0644\u0632\u0644\u0627\u062c\u0629 \u0645\u0639 \u0648\u0636\u0639 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0648\u0633\u0627\u062f\u0629 \u0648\u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0645\u0646\u0635\u0629 \u0627\u0644\u0642\u062f\u0645.\n\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0645\u0633\u0627\u0641\u0629 \u0623\u0648\u0633\u0639 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u062f\u0641\u0639 \u0639\u0644\u0649 \u0645\u0646\u0635\u0629 \u0627\u0644\u0642\u062f\u0645 \u0644\u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u064a\u0643 \u0648\u062a\u0635\u0648\u064a\u0628 \u0631\u0643\u0628\u062a\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0639\u0646\u062f \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0628\u0637\u0621 \u0644\u062a\u0639\u0648\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0740","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0740-tj41Nu6.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0740-tj41Nu6.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"76c3cd15-5c66-5700-8d8a-28c9f59dfe61","source_id":"1391","name_en":"sled calf press on leg press","name_ar":"\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0632\u0644\u0627\u062c\u0629 \u0627\u0644\u0639\u062c\u0644 \u0639\u0644\u0649 \u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0633\u0627\u0642","match_names":["sled calf press on leg press"],"muscle":"calves","equipment":"sled_machine","aliases":["sled calf press on leg press"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.\nPlace your feet shoulder-width apart on the sled, with your toes pointing forward.\nRelease the safety handles and push the sled away from you by extending your knees and ankles.\nPause for a moment at the top of the movement, then slowly lower the sled back down by bending your knees and ankles.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0645\u0642\u0639\u062f \u0622\u0644\u0629 \u0636\u063a\u0637 \u0627\u0644\u0623\u0631\u062c\u0644 \u0628\u062d\u064a\u062b \u062a\u0646\u062d\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b \u0639\u0646\u062f\u0645\u0627 \u062a\u0643\u0648\u0646 \u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0632\u0644\u0627\u062c\u0629.\n\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0632\u0644\u0627\u062c\u0629 \u0628\u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u062d\u0631\u0631 \u0645\u0642\u0627\u0628\u0636 \u0627\u0644\u0623\u0645\u0627\u0646 \u0648\u0627\u062f\u0641\u0639 \u0627\u0644\u0632\u0644\u0627\u062c\u0629 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062a\u0645\u062f\u064a\u062f \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0643\u0627\u062d\u0644\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u0632\u0644\u0627\u062c\u0629 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0641\u0644 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0643\u0627\u062d\u0644\u064a\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1391","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"calves","secondary_muscles":["hamstrings","quadriceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1391-ykHcWme.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1391-ykHcWme.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"9218b1c6-a1a7-5bfc-8d37-d79c45d820c4","source_id":"0741","name_en":"sled closer hack squat","name_ar":"\u0632\u0644\u0627\u062c\u0629 \u0623\u0642\u0631\u0628 \u0625\u0644\u0649 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0627\u0644\u0627\u062e\u062a\u0631\u0627\u0642","match_names":["sled closer hack squat"],"muscle":"glutes","equipment":"sled_machine","aliases":["sled closer hack squat"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the sled machine to a comfortable weight and position yourself with your back against the pad.\nPlace your feet shoulder-width apart on the platform, toes slightly pointed outwards.\nGrip the handles on the sides of the machine for stability.\nEngage your core and slowly lower your body by bending your knees and hips, keeping your back straight.\nContinue lowering until your thighs are parallel to the ground or slightly below.\nPause for a moment at the bottom, then push through your heels to extend your legs and return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0622\u0644\u0629 \u0627\u0644\u0632\u0644\u0627\u062c\u0629 \u0639\u0644\u0649 \u0648\u0632\u0646 \u0645\u0631\u064a\u062d\u060c \u062b\u0645 \u0636\u0639 \u0646\u0641\u0633\u0643 \u0645\u0639 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0648\u0633\u0627\u062f\u0629.\n\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u0646\u0635\u0629 \u0628\u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0635\u0627\u0628\u0639 \u0627\u0644\u0642\u062f\u0645 \u062a\u0634\u064a\u0631 \u0642\u0644\u064a\u0644\u0627\u064b \u0625\u0644\u0649 \u0627\u0644\u062e\u0627\u0631\u062c.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0627\u0644\u0645\u0648\u062c\u0648\u062f\u0629 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a \u0627\u0644\u0645\u0627\u0643\u064a\u0646\u0629 \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u062b\u0628\u0627\u062a.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0648\u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0648\u0627\u0644\u062d\u0641\u06