\u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u0641\u0643 \u0627\u0644\u062d\u062f\u064a\u062f \u0648\u062e\u0641\u0636\u0647 \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0645\u0637\u0648\u064a\u064a\u0646 \u0642\u0644\u064a\u0644\u0627\u064b \u0644\u0644\u062f\u0627\u062e\u0644.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u0645\u0639 \u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0757","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["shoulders","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0757-5v7KYld.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0757-5v7KYld.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"015a034c-fbab-595b-8e32-b58a76c1b24f","source_id":"0758","name_en":"smith incline reverse-grip press","name_ar":"\u0633\u0645\u064a\u062b \u0627\u0646\u062d\u062f\u0631 \u0627\u0644\u0635\u062d\u0627\u0641\u0629 \u0642\u0628\u0636\u0629 \u0639\u0643\u0633\u064a\u0629","match_names":["smith incline reverse-grip press"],"muscle":"chest","equipment":"smith_machine","aliases":["smith incline reverse-grip press"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the seat of the smith machine to a comfortable incline angle.\nSit on the machine with your back against the pad and your feet flat on the ground.\nGrasp the bar with an overhand grip that is slightly wider than shoulder-width apart.\nUnrack the bar and lower it slowly towards your chest, keeping your elbows tucked in.\nPause for a moment when the bar is just above your chest.\nPush the bar back up to the starting position, fully extending your arms.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0645\u0642\u0639\u062f \u0645\u0627\u0643\u064a\u0646\u0629 \u0633\u0645\u064a\u062b \u0639\u0644\u0649 \u0632\u0627\u0648\u064a\u0629 \u0645\u064a\u0644 \u0645\u0631\u064a\u062d\u0629.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u0632 \u0645\u0639 \u0648\u0636\u0639 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0648\u0633\u0627\u062f\u0629 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629 \u062a\u0643\u0648\u0646 \u0623\u0639\u0631\u0636 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u0641\u0643 \u0627\u0644\u0628\u0627\u0631 \u0648\u062e\u0641\u0636\u0647 \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0645\u0637\u0648\u064a\u064a\u0646 \u0644\u0644\u062f\u0627\u062e\u0644.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0639\u0646\u062f\u0645\u0627 \u064a\u0643\u0648\u0646 \u0627\u0644\u0634\u0631\u064a\u0637 \u0623\u0639\u0644\u0649 \u0635\u062f\u0631\u0643 \u0645\u0628\u0627\u0634\u0631\u0629\u064b.\n\u0627\u062f\u0641\u0639 \u0627\u0644\u0628\u0627\u0631 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u0645\u0639 \u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0758","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["triceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0758-78VqWQK.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0758-78VqWQK.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"5a2ab4e5-76ba-5edc-86fa-8dd6dd8bf3c2","source_id":"0759","name_en":"smith incline shoulder raises","name_ar":"\u0633\u0645\u064a\u062b \u064a\u0631\u0641\u0639 \u0627\u0644\u0643\u062a\u0641 \u0627\u0644\u0645\u0646\u062d\u062f\u0631","match_names":["smith incline shoulder raises"],"muscle":"serratus_anterior","equipment":"smith_machine","aliases":["smith incline shoulder raises"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the smith machine to an incline position.\nStand facing the machine with your feet shoulder-width apart.\nGrasp the bar with an overhand grip, slightly wider than shoulder-width apart.\nKeep your back straight and core engaged.\nRaise the barbell up towards the ceiling, leading with your elbows.\nPause for a moment at the top, then slowly lower the barbell back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0622\u0644\u0629 \u0633\u0645\u064a\u062b \u0639\u0644\u0649 \u0648\u0636\u0639 \u0645\u0646\u062d\u062f\u0631.\n\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0622\u0644\u0629 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646 \u0627\u0644\u0631\u062c\u0644\u064a\u0646 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0646\u0634\u0627\u0637\u0643 \u0627\u0644\u0623\u0633\u0627\u0633\u064a.\n\u0627\u0631\u0641\u0639 \u0627\u0644\u0628\u0627\u0631 \u0644\u0644\u0623\u0639\u0644\u0649 \u0646\u062d\u0648 \u0627\u0644\u0633\u0642\u0641\u060c \u0645\u0639 \u062a\u062d\u0631\u064a\u0643 \u0645\u0631\u0641\u0642\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0759","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"serratus anterior","secondary_muscles":["deltoids","trapezius"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0759-ayAHcEm.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0759-ayAHcEm.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"9cfb3bcf-6367-55d6-89ac-2c41150dd7ef","source_id":"0760","name_en":"smith leg press","name_ar":"\u0633\u0645\u064a\u062b \u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0633\u0627\u0642","match_names":["smith leg press"],"muscle":"glutes","equipment":"smith_machine","aliases":["smith leg press"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the seat and footplate of the smith machine to a comfortable position.\nSit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.\nGrasp the handles or sides of the machine for stability.\nPush the footplate away from you by extending your legs, keeping your back against the backrest.\nPause for a moment at the fully extended position.\nSlowly bend your knees and lower the footplate back towards you, returning to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0644\u0648\u062d\u0629 \u0627\u0644\u0642\u062f\u0645 \u0644\u0622\u0644\u0629 \u0633\u0645\u064a\u062b \u0639\u0644\u0649 \u0648\u0636\u0639 \u0645\u0631\u064a\u062d.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u0632 \u0645\u0639 \u0648\u0636\u0639 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0645\u0633\u0646\u062f \u0627\u0644\u0638\u0647\u0631\u060c \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u062a\u0628\u0627\u0639\u062f\u062a\u064a\u0646 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0639\u0644\u0649 \u0644\u0648\u062d\u0629 \u0627\u0644\u0642\u062f\u0645.\n\u0623\u0645\u0633\u0643 \u0628\u0645\u0642\u0627\u0628\u0636 \u0623\u0648 \u062c\u0648\u0627\u0646\u0628 \u0627\u0644\u0645\u0627\u0643\u064a\u0646\u0629 \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u062b\u0628\u0627\u062a.\n\u0627\u062f\u0641\u0639 \u0644\u0648\u062d\u0629 \u0627\u0644\u0642\u062f\u0645 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0645\u062f \u0633\u0627\u0642\u064a\u0643\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0642\u0627\u0628\u0644 \u0645\u0633\u0646\u062f \u0627\u0644\u0638\u0647\u0631.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0645\u0645\u062a\u062f \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0628\u0637\u0621 \u0648\u062e\u0641\u0636 \u0627\u0644\u0635\u0641\u064a\u062d\u0629 \u0627\u0644\u0642\u062f\u0645\u064a\u0629 \u0646\u062d\u0648\u0643\u060c \u0648\u0627\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0760","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0760-7zdxRTl.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0760-7zdxRTl.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"00d0f6bd-3091-5aa8-831f-4c66fd5f88d1","source_id":"1434","name_en":"smith low bar squat","name_ar":"\u0633\u0645\u064a\u062b \u0634\u0631\u064a\u0637 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0627\u0644\u0645\u0646\u062e\u0641\u0636","match_names":["smith low bar squat"],"muscle":"glutes","equipment":"smith_machine","aliases":["smith low bar squat"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Set up the smith machine with the barbell at a height that allows you to comfortably rest it on your upper back.\nStand with your feet shoulder-width apart, toes slightly turned outwards.\nStep under the bar and position it across your upper back, resting it on your traps.\nGrip the bar with your hands slightly wider than shoulder-width apart.\nUnrack the bar by straightening your legs and stepping back from the rack.\nTake a deep breath and brace your core.\nInitiate the squat by pushing your hips back and bending your knees.\nLower your body until your thighs are parallel to the ground or slightly below.\nKeep your chest up and your back straight throughout the movement.\nDrive through your heels to stand back up, extending your hips and knees.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u0625\u0639\u062f\u0627\u062f \u0622\u0644\u0629 \u0633\u0645\u064a\u062b \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u064a\u0633\u0645\u062d \u0644\u0643 \u0628\u0648\u0636\u0639\u0647 \u0628\u0634\u0643\u0644 \u0645\u0631\u064a\u062d \u0639\u0644\u0649 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0638\u0647\u0631\u0643.\n\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u0645\u062a\u062c\u0647\u0629 \u0646\u062d\u0648 \u0627\u0644\u062e\u0627\u0631\u062c \u0642\u0644\u064a\u0644\u0627\u064b.\n\u062e\u0637\u0648\u0629 \u062a\u062d\u062a \u0627\u0644\u0634\u0631\u064a\u0637 \u0648\u0636\u0639\u0647 \u0639\u0644\u0649 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0638\u0647\u0631\u0643\u060c \u0645\u0639 \u0648\u0636\u0639\u0647 \u0639\u0644\u0649 \u0623\u0641\u062e\u0627\u062e\u0643.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0646\u0637\u0627\u0642 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u0627\u064b \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u0641\u0643 \u0627\u0644\u0634\u0631\u064a\u0637 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0641\u0631\u062f \u0633\u0627\u0642\u064a\u0643 \u0648\u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u0639\u0646 \u0627\u0644\u062d\u0627\u0645\u0644.\n\u062e\u0630 \u0646\u0641\u0633\u064b\u0627 \u0639\u0645\u064a\u0642\u064b\u0627 \u0648\u0627\u0633\u062a\u0639\u062f \u0644\u0642\u0644\u0628\u0643.\n\u0627\u0628\u062f\u0623 \u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062f\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641 \u0648\u062b\u0646\u064a \u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646.\n\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0641\u062e\u0630\u0627\u0643 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636 \u0623\u0648 \u0623\u0642\u0644 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0635\u062f\u0631\u0643 \u0645\u0631\u062a\u0641\u0639\u064b\u0627 \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0637\u0648\u0627\u0644 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0642\u0645 \u0628\u0627\u0644\u0642\u064a\u0627\u062f\u0629 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0643\u0639\u0628\u064a\u0643 \u0644\u0644\u0648\u0642\u0648\u0641 \u0627\u062d\u062a\u064a\u0627\u0637\u064a\u064b\u0627\u060c \u0648\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1434","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1434-RGLscZM.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1434-RGLscZM.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"62868d50-50bf-5709-850c-542cb8da04dd","source_id":"1683","name_en":"smith machine bicep curl","name_ar":"\u0622\u0644\u0629 \u0633\u0645\u064a\u062b \u0644\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646","match_names":["smith machine bicep curl"],"muscle":"biceps","equipment":"smith_machine","aliases":["smith machine bicep curl"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the height of the smith machine bar to be at waist level.\nStand facing the smith machine with your feet shoulder-width apart.\nGrasp the bar with an underhand grip, hands slightly wider than shoulder-width apart.\nKeep your elbows close to your sides and your upper arms stationary.\nExhale and curl the bar up towards your shoulders, contracting your biceps.\nPause for a moment at the top of the movement, squeezing your biceps.\nInhale and slowly lower the bar back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0631\u062a\u0641\u0627\u0639 \u0634\u0631\u064a\u0637 \u0622\u0644\u0629 \u0633\u0645\u064a\u062b \u0644\u064a\u0643\u0648\u0646 \u0639\u0646\u062f \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u062e\u0635\u0631.\n\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0622\u0644\u0629 \u0633\u0645\u064a\u062b \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0628\u0627\u0631 \u0628\u0642\u0628\u0636\u0629 \u0633\u0641\u0644\u064a\u0629\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0634\u0643\u0644 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0628\u0642\u0650 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628\u064a\u0643 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u064a\u0646 \u062b\u0627\u0628\u062a\u064a\u0646.\n\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0627\u0644\u0628\u0627\u0631 \u0646\u062d\u0648 \u0643\u062a\u0641\u064a\u0643\u060c \u0645\u0639 \u062a\u0642\u0644\u064a\u0635 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u0628\u0627\u0631 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1683","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1683-zILLZ98.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1683-zILLZ98.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"04b9eee8-f3d1-5849-8510-0e959322ea87","source_id":"1625","name_en":"smith machine decline close grip bench press","name_ar":"\u062c\u0647\u0627\u0632 \u0633\u0645\u064a\u062b \u0644\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0645\u0642\u0627\u0639\u062f \u0627\u0644\u0628\u062f\u0644\u0627\u0621 \u0628\u0642\u0628\u0636\u0629 \u0642\u0631\u064a\u0628\u0629","match_names":["smith machine decline close grip bench press"],"muscle":"triceps","equipment":"smith_machine","aliases":["smith machine decline close grip bench press"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the bench on the smith machine to a decline position.\nLie down on the bench with your feet firmly planted on the ground.\nGrasp the barbell with a close grip, slightly narrower than shoulder-width apart.\nUnrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.\nPause for a moment when the barbell is just above your chest.\nPush the barbell back up to the starting position, fully extending your arms.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0644\u0645\u0642\u0639\u062f \u0627\u0644\u0645\u0648\u062c\u0648\u062f \u0639\u0644\u0649 \u0622\u0644\u0629 \u0633\u0645\u064a\u062b \u0639\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0627\u0646\u062e\u0641\u0627\u0636.\n\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0642\u0648\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0645\u062d\u0643\u0645\u0629\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0623\u0636\u064a\u0642 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u0641\u0643 \u0627\u0644\u062d\u062f\u064a\u062f \u0648\u062e\u0641\u0636\u0647 \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0633\u0645\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0639\u0646\u062f\u0645\u0627 \u064a\u0643\u0648\u0646 \u0627\u0644\u062d\u062f\u064a\u062f \u0641\u0648\u0642 \u0635\u062f\u0631\u0643 \u0645\u0628\u0627\u0634\u0631\u0629\u064b.\n\u0627\u062f\u0641\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u0645\u0639 \u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1625","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["chest","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1625-yB9SvIF.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1625-yB9SvIF.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"a66113e5-b834-5bab-8aa2-3249e1cb92f7","source_id":"1752","name_en":"smith machine incline tricep extension","name_ar":"\u0622\u0644\u0629 \u0633\u0645\u064a\u062b \u062a\u0646\u062d\u062f\u0631 \u062a\u0645\u062f\u064a\u062f \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633","match_names":["smith machine incline tricep extension"],"muscle":"triceps","equipment":"smith_machine","aliases":["smith machine incline tricep extension"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the seat of the smith machine so that the bar is at shoulder height.\nSit on the bench with your back against the pad and your feet flat on the ground.\nGrasp the bar with an overhand grip, slightly wider than shoulder-width apart.\nExtend your arms fully, lifting the bar off the rack and holding it directly above your chest.\nLower the bar slowly towards your forehead, keeping your elbows close to your head.\nPause for a moment at the bottom, then push the bar back up to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0645\u0642\u0639\u062f \u0622\u0644\u0629 \u0633\u0645\u064a\u062b \u0628\u062d\u064a\u062b \u064a\u0643\u0648\u0646 \u0627\u0644\u0634\u0631\u064a\u0637 \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0645\u0639 \u0648\u0636\u0639 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0648\u0633\u0627\u062f\u0629 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646 \u0627\u0644\u0631\u062c\u0644\u064a\u0646 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644\u060c \u0648\u0627\u0631\u0641\u0639 \u0627\u0644\u0628\u0627\u0631 \u0639\u0646 \u0627\u0644\u062d\u0627\u0645\u0644 \u0648\u0623\u0645\u0633\u0643\u0647 \u0645\u0628\u0627\u0634\u0631\u0629 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643.\n\u0627\u062e\u0641\u0636 \u0627\u0644\u0628\u0627\u0631 \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u062c\u0628\u0647\u062a\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u0631\u0623\u063