neyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0762-nFUwqG6.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0762-nFUwqG6.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"159f449f-6550-588a-8ef2-bf74155b1912","source_id":"0763","name_en":"smith reverse calf raises","name_ar":"\u0633\u0645\u064a\u062b \u064a\u0631\u0641\u0639 \u0631\u0628\u0644\u0629 \u0627\u0644\u0633\u0627\u0642 \u0628\u0634\u0643\u0644 \u0639\u0643\u0633\u064a","match_names":["smith reverse calf raises"],"muscle":"calves","equipment":"smith_machine","aliases":["smith reverse calf raises"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the smith machine bar to a height just below your shoulders.\nStand facing the bar with your feet hip-width apart and toes pointing forward.\nPlace the balls of your feet on the edge of a step or platform, with your heels hanging off.\nHold onto the bar for support, keeping your back straight and core engaged.\nRaise your heels as high as possible, lifting your body weight onto the balls of your feet.\nPause for a moment at the top, then slowly lower your heels back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0634\u0631\u064a\u0637 \u0622\u0644\u0629 \u0633\u0645\u064a\u062b \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0623\u0633\u0641\u0644 \u0643\u062a\u0641\u064a\u0643 \u0645\u0628\u0627\u0634\u0631\u0629\u064b.\n\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0634\u0631\u064a\u0637 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0648\u0631\u0643 \u0648\u062a\u0648\u062c\u064a\u0647 \u0623\u0635\u0627\u0628\u0639 \u0627\u0644\u0642\u062f\u0645 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0636\u0639 \u0645\u0642\u062f\u0645\u0629 \u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u062d\u0627\u0641\u0629 \u0627\u0644\u062f\u0631\u062c\u0629 \u0623\u0648 \u0627\u0644\u0645\u0646\u0635\u0629\u060c \u0645\u0639 \u062a\u0639\u0644\u064a\u0642 \u0643\u0639\u0628\u064a\u0643.\n\u062a\u0645\u0633\u0643 \u0628\u0627\u0644\u0628\u0627\u0631 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0645\u060c \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0646\u0634\u0627\u0637\u0643 \u0627\u0644\u0623\u0633\u0627\u0633\u064a.\n\u0627\u0631\u0641\u0639\u064a \u0643\u0639\u0628\u064a\u0643 \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0645\u0645\u0643\u0646\u060c \u0648\u0627\u0631\u0641\u0639\u064a \u0648\u0632\u0646 \u062c\u0633\u0645\u0643 \u0639\u0644\u0649 \u0645\u0634\u0637 \u0642\u062f\u0645\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0643\u0639\u0628\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0763","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"calves","secondary_muscles":["hamstrings"],"catalogue_media":{"poster":"https://raw.github